#include <Arduino.h>

const uint8_t BUZZER_PIN = 6;
unsigned long burstStart = 0;
bool sounding = false;

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(BUZZER_PIN, LOW);
  burstStart = millis();
  tone(BUZZER_PIN, 1000);
  sounding = true;
}

void loop() {
  unsigned long now = millis();
  if ((unsigned long)(now - burstStart) >= 2000UL) {
    burstStart += 2000UL;
    tone(BUZZER_PIN, 1000);
    sounding = true;
  }
  if (sounding && (unsigned long)(now - burstStart) >= 200UL) {
    noTone(BUZZER_PIN);
    digitalWrite(BUZZER_PIN, LOW);
    sounding = false;
  }
}
